    awardType:"其他",
    photoKeywords:["白鹅", "车厢"],
    photoNumber:"009", photoBatch:2,
    salesFactor:96, newsValue:24,
    title:"一只白鹅搭早班车坐了六站",
    lead:"本报讯 昨日早晨，去河西的班车在竹桥站上来一只白鹅，它坐了六站才在终点下车。有乘客称有人给鹅买票，车队找到残缺的票根，目前还对不上购票人。",
    body:[
      "车队已将白鹅留在河西终点站值班室。昨日7时许，该车在竹桥站停车，白鹅跟在乘客脚边从后门上车，司机直到驶出站点才从后视镜里看见它。到河西终点后，乘客先下车，车队请在站上卖豆腐的摊主把鹅领到值班室。",
      "“我听说有人替鹅付了一元。那人把钱递过去，后排就说是给鹅买票。”坐在前排的乘客高志勇说。",
      "另一名乘客称，递钱的是给孩子补票的家长。“我没看清谁递的钱。票夹底下是压过一元钱，当时车上人太多。”当班售票员何宁说。记者在调度室查到该班车的票号连续，核对的票根上只有票价和车次。",
      "卖豆腐的刘彩霞起初以为是自家走失的那只，翻看才发现，这只鹅两脚蹼都齐全，她家的鹅左脚缺了一截。她只好先给鹅喂了半碗饭。截至记者发稿，白鹅仍拴在河西终点值班室，不时朝门口等车的人叫。车队已查过沿途站点，还没有失主来认。"
    ],
    short:"本报讯 昨晨，一只白鹅随乘客在竹桥站上了去河西的早班车，坐过六站才被领下。乘客对是否有人替鹅买票说法不一，车队找到的残票也无法对应购票人。截至记者发稿，白鹅已由终点站值班室照看，暂未有人认领。",
    risk:{"probability":0.31,"severity":"minor","correction":"本报关于早班车上那只鹅单独购票的说法有误。车队核对票根后确认，车票由一名乘客购买，鹅未单独购票。"}
