    lead:"本报讯 昨日，三位顾客拿着内容相同的收据，到临渡五金巷修表铺认领同一只蓝壳闹钟。店主凭收据背面印迹认出其中一只，另外两只随后在店内找到。",
    body:[
      "记者在修表铺看到，三张送修收据都写着“蓝壳、左侧缺脚”，收件日期相同，均未登记送修者姓名。最先摆上柜台的闹钟有一道擦痕，背板还有针眼，恰好分别符合两名顾客描述的记号。第三名顾客要求店主先把钟上紧，钟一响，他说钟罩里还有一声小响动。",
      "“我的钟罩里有颗纽扣，闹起来比别的钟多一声。”附近食堂厨师徐志强说。他的收据背面留着半枚蓝色印迹，修表铺与隔壁粮店对照当天旧账，确认徐志强买面时用它记过账。店主拆开钟罩，果然找到一颗旧纽扣。",
      "“三只都缺左脚，收据光写缺脚没法分。”修表师傅周立新说。店员随后在零件盒和试响用的窗台上分别找到其余两只，核对外壳后归还顾客。截至昨晚，三只钟均已送还。修表铺把柜上的旧收件单换掉，新单增加送修人姓名和外壳特征两栏。"
    ],
    short:"本报讯 昨日，五金巷三名顾客拿着内容相同的送修票来领蓝壳闹钟。修表师傅核对票背印记并拆钟找出纽扣，认出了柜上那只。其余两只随后从零件盒和窗台找回，三只钟均已交还原主，修表铺已改收件单。"
