    short:"本报讯 临渡文化站昨日17时30分在广场试音，误把陆师傅因牙疼换班的便条播了三遍，电影开场前有7名邻居到陆家探望。陆师傅已就医，推银幕车的活由同事接手，当晚电影照常放映。文化站从下周起改用专门的试音稿。"
