    lead:"本报讯 昨日上午，临渡广场值班室把一年来拾到的钥匙、饭盒等物品摆上台阶集中招领。第一件被领走的失物是一扇蓝木门，主人凭门板下方一个供鹅进出的三角缺口认出了它。",
    body:[
      "值班室公布的首批招领清单包括23把钥匙、数件衣物、两副假牙和一扇木门。记者看到，门板上的金属门牌仍在，但值班员照门牌查找时发现，那个地址如今是家布店。蓝木门是冬季大风过后在河边捡到的，因为无法放进柜子，几个月来一直靠在值班室背后。",
      "“下面有个缺口，是给鹅开的。我还没走到跟前就跟他们说了。”在广场附近卖煤球的孙彩霞说。值班员掀开挡在木门下沿的纸，缺口果然是三角形。孙彩霞还出示了煤棚的旧照片，登记后用板车把门运走。",
      "“平时领钥匙得说清有几把，没想到今天还得验个鹅洞。她把照片一拿出来，门上的缺口正好对上。”广场值班员林凯说。",
      "昨日还有一只饭盒被一位在摊前站了半天的失主认领，他最初把饭盒当成了收钥匙的盘子。截至记者发稿，值班室只发还了木门和饭盒。23把钥匙和两副假牙仍无人认领，值班室保留了按拾物地点编排的清单。"
    ],
    short:"本报讯 临渡广场昨日集中招领失物，展出的物品包括23把钥匙、两副假牙和一扇从河边捡来的蓝木门。门主说出了门板下方给鹅留的缺口，并拿出煤棚旧照，成为头一个领回失物的人。截至发稿，又有一只饭盒找到失主。"
