      "“化验没做，退一块六。我在两座楼之间来回跑，医生可算签了字，到了窗口又赶上交班。”68岁的患者李国庆说。记者现场看到，大厅告示写了各缴费窗口的编号，退费要带的票据和中午办理时间未列在上面。收费员向记者展示了此前出现对账差异的两份退费凭证，签字栏均由他人代签。",
      "“有的病人腿脚不好，让他上楼找医生，再下楼找窗口，这一趟够累的。以后先到导医台，医生在哪儿由我们去找。”院方门诊办李主任说。医院计划从下周起执行，在收费楼公布午间退费窗口。门诊办提醒，办理时请携带原收费票及未执行项目的单据，可先到一楼导医台询问。"
