    short:"本报讯 昨日记者跟访临渡市二院三名门诊退费患者，办理耗时18至47分钟，最慢一笔为1.6元化验费。院方拟从下周起由导医查票后联系签字医生，并公布午间可退费的窗口，退费时须带原收费票及未做项目的单据。"
