    short:"本报讯 昨日临渡两家橱柜店看同一幅图后报每米480元和760元，记者按相同材料、尺寸和安装要求补齐项目后，总价仅差110元。转角、吊柜和五金的计价方式各异，下单前可要求商家逐项书面报价，并把水管位置量进去。"
