    lead:"本报讯 昨晨，临渡东门粮店外传出下周一可凭户口簿低价买米的消息，多名居民到店询问。记者拿到的复印件缺少落款和文号，柜台仍按原价销售。",
    body:[
      "到昨日7时，粮店尚未开门，门外已有居民带户口簿等候。流传的字条称，下周一开始每户可低价购买一袋米，先到先领。记者手中的两份复印件日期相同，右下方均缺一角，不能辨认完整落款和文号，也没有写每袋重量。记者对照两份纸边的黑印，四处位置一致，无法确认是否来自不同渠道。",
      "“我听说一户能买一袋。早上问的人多，我就回家把户口簿拿上了。”附近卖煤球的摊主何立德说。隔壁复印铺店员称有人来印过相近的纸，原件已由来客带走，未留下姓名。",
      "“昨天来问的人多，我把柜台上的价牌拿给他们看。我下班前没见过什么新单子。”粮店值班员赵春花说。记者将一份复印件留给店里查验。截至记者发稿，窗口未张贴任何低价米通知。粮店提醒，有购米需求的居民先看正式价牌，是否有新货及袋重可直接向柜台询问。"
    ],
    short:"本报讯 昨晨，东门粮店外有居民带户口簿询问下周一的低价米。记者核对两份复印件，右下角均缺落款和文号，纸上也未写明袋重。粮店值班员未收到新进货单，柜台仍按原价销售。截至发稿，店里暂未贴出低价米告示。",
