      "“我还在凳子上等，以为家里人忘了。他们每周都往这儿打电话。”附近钟表店学徒吴鑫说。得知电话拆除后，他到报亭重新约好下一次通话。附近几家旅馆已经把原来贴在柜台的公话提示换掉。",
      "“只要事先跟我们打声招呼，叫得着的人，我们可以帮忙喊一声。我七点收摊，再晚这电话就没人接了。”报亭经营者刘福生说。街道表示，原公话亭旁的长凳将继续留作候车用。仍与外地亲友约定用原号码通话的居民，请及时改约电话号码和时段。"
