    lead:"本报讯 昨日，记者在临渡东环线实测六个停靠点，发现新换的低地板公交在其中三站仍难供轮椅乘客独立上车。车队拟先调整缫丝厂和粮库两站的停车位置。",
    body:[
      "昨日9时许，陈建军推母亲到缫丝厂站试乘，司机放下踏板后，板尖抵在路沿侧面，车内下来两名乘客帮忙，才把轮椅抬上车。“还是请了人。车一到，我们以为有板就能自己上。”陪同乘车的陈建军说。记者随车走完东环线六站，另外两处问题站点为粮库站和石板桥站。",
      "实测发现，缫丝厂站砖台偏高，粮库站停车点有排水沟，石板桥站靠边位置常停满自行车。其余三站踏板能够落稳。“车靠里一点，板碰着砖头，靠外一点又过不去水沟。同一辆车，换个站就得换个停法。”当班司机徐小平说。记者查看车队的交接单，表上有车型更换记录，尚未填写各站放板条件。",
      "车队与交通管理人员商定，缫丝厂及粮库站先就近试停，具体位置会写在原站牌上。石板桥站暂由车队安排人员协助乘降，后续调整要等自行车停放位置协调完毕。需要协助的乘客可在上车前告知司机。"
    ],
    short:"本报讯 昨日记者随东环线低地板公交走完六站，发现缫丝厂、粮库和石板桥三站的踏板难以落稳，轮椅乘客仍需协助。车队拟先就近试调缫丝厂、粮库停车点，石板桥由车队暂时安排人员协助，具体位置以站牌告示为准。"
