      "“我听到一声响，后来脚底下踩的就是窗玻璃。有人在外面托住我，我才敢往下爬。”乘客何建军说。他在市二院处理擦伤后回站领取行包。昨日上午客运站逐一联系家属，并安排转车，未让乘客重复购票。",
