      "事发时，工人正在车间内将成品移往库房。记者在警戒线外看到，中跨屋面塌下，厂里的叉车停在破开的门边。消防人员先支护仍悬在半空的构件，再按工友指出的位置搜救。两名伤者先被送出，第三名获救者在货架旁被发现。",
      "“原来几个人都在同一排码货。我出去拉车，只转了一趟，回来门口就全是灰。”厂内装卸工马立新说。厂方交出当班名单，确认隔壁车间当时无人作业。供电所已断开事故区电源，厂区其余工段暂停生产。",
