    short:"本报讯 昨日14时20分，临渡城西预制厂旧车间屋面坍塌。消防人员完成临时支护后救出3名工人，另1名被困工人已确认死亡。市事故调查组已调取厂房图纸。三名获救者均送医，截至昨晚两人仍留院治疗，一人已离院。"
