    lead:"本报讯 昨日，记者在临渡南街粮摊按10斤购买散米，在市场公平秤上复秤，扣除包装后只有8.6斤。市场管理所随后封存涉事秤具。",
    body:[
      "记者随一位买米人到该摊，先看摊上归零，再用另一只空袋装米，付款后请摊主在票上写下10斤和单价。到市场服务台复秤，工作人员分别称了带袋和空袋，将两行读数写在同一张复核单上。另一笔5斤米的购买也经当面复称，净重4.4斤。",
      "“我在这儿买了快一年，平时提起来也觉得沉，哪想过还要抄张小票再称一遍。”附近饭店帮工吴春梅说。记者用同一服务台的秤复核另一家摊位，同样记下袋重，那笔买卖的读数与票据相符。两笔复核均在市场工作人员面前进行，原购物票据由服务台留复印件。",
      "“这秤昨天从仓里搬出来，我没换过砝码。你们拿去验，少的那点我先退。”涉事摊主陈国庆说。",
      "市场管理所已对现场计量作记录，秤具由计量人员另行检验，暂未认定短秤原因。购买过该摊散米的顾客可持原票到服务台复核。"
    ],
    short:"本报讯 昨日记者在临渡南街粮摊购买10斤散米，公平秤复核净重8.6斤，另一笔5斤米复秤为4.4斤。服务台已记录袋重和称量数据，市场管理所封存涉事秤具送检。顾客可持原票到服务台复核，短秤原因待查。"
