    lead:"本报讯 昨日，记者核对临渡北门百货一款电饭锅的旧票和新价牌，发现海报所称直降200元的促销价，与1个月前同款商品的实际成交价相同。市物价检查人员已收取价牌和销货账。",
    body:[
      "促销海报将电饭锅的现价标作198元，在旁边划掉398元。记者分两次进店抄下货号和容量，取到一张试购小票，又向此前购货的居民借到上月发票。两份票金额都为198元，货号一致。商场另有同系列不同容量商品，记者未把它们纳入比较。海报贴在柜前，记者未看见另有说明旧价的纸牌。",
      "“我特意把旧票拿到柜台，问店员我是不是早买便宜了。他看了半天，先叫我到服务台等。”上月购锅的顾客孙红霞说。记者在服务台看到，促销告示没有注明398元对应的销售日期或渠道。",
      "“海报是供货方送来的，那条划线价经手的人今天没来。我能拿出来的是店里这本账。”百货家电柜主管朱志明说。商场昨日下午撤下海报，按现价照常售卖。物价检查人员正查活动前的实际成交记录，暂未对广告作出处理决定。"
    ],
    short:"本报讯 临渡北门百货一款电饭锅标榜直降200元，售价198元。记者将促销小票与上月同货号发票对照，成交价相同。商场称海报由供货方提供，已撤下宣传。市物价检查人员已收取销货账，正在查划线价依据。"
