    short:"本报讯 临渡市建筑安全监督站昨日公布抽检结果，石门路工地送检的8顶安全帽中5顶未达标。记者在工人代表和安全员见证下封样，工地已暂停发放同批帽具，并交出送货单。供货来源和实际入库量仍在核查。"
