    short:"本报讯 临渡一家证券营业部有19笔柜台委托遭股民质疑，纸回单均未印受理时刻。记者带四张回单核对，三张找到对应电脑记录，另有一张尚待核实。营业部已换回能印时间的机器，旧单持有人仍在等答复。"
