    short:"本报讯 临渡柳桥路影碟摊将一批VCD当正版出售。记者在三处购买6张送核，封套所列发行单位确认其中5张查不到发行记录。稽查人员已取走同批碟片，正在追查供货人。已售影碟能否退款，摊主未作承诺。"
