      "记者在第一家网吧守了40分钟，7名穿校服的学生先后走进店里。其中几人交过钱就坐下，柜台没问年龄。记者后来到另一家，看见工作人员让学生写个姓便放行。两家门外都贴着未成年人禁入的牌子，柜台本上没有相应的年龄记录。几人一直坐到天快黑，陆续有家长来找。",
