    short:"本报讯 临渡河西三户居民昨日给新买的轿车画了三个停车框。实车试摆时，有的开不了车门，有的挡住送煤车。最后轿车停到巷外，送煤的板车正好靠进墙边的空框。街坊刷掉两框，保留一个供卸煤用。"
