const LIBRARY_PHOTO_FOLDER = '素材/第四轮E-第一批待审';
const SECOND_LIBRARY_PHOTO_FOLDER = '素材/第五轮-第二批资料图';
const PHOTO_LOCATIONS = ['菜场', '客运站', '厂门', '老街', '河堤', '学校', '医院门口', '百货柜台', '市民广场', '足球场'];
const LIBRARY_PHOTOS = new Map([
  ...STORIES.filter(story => story.photoNumber).map(story => {
    const folder = story.photoBatch === 2 ? SECOND_LIBRARY_PHOTO_FOLDER : LIBRARY_PHOTO_FOLDER;
    return [story.id, {name:story.photoKeywords[0], file:`${folder}/专属图/${story.photoNumber}.jpg`}];
  }),
  ...PHOTO_LOCATIONS.map(name => [`location:${name}`, {
    name, file:`${LIBRARY_PHOTO_FOLDER}/空镜/${name}.jpg`, location:true
  }])
]);

function libraryPhotoId(story) {
  if (story.photoNumber) return story.id;
  return story.photoLocation ? `location:${story.photoLocation}` : null;
}

const LIBRARY_PHOTO_IDS = new Map(STORIES.map(story => [story.id, libraryPhotoId(story)]));
